response.value:
Understood: we’ll keep everything **strictly local-only**. The app will use the saved category to show the regular or add-on flow, while recognizing that a determined player can change it. We’ll build this in small steps and pause after each one. **Nothing needs to be committed or pushed until the complete feature is ready.**

### Step 1: Create the game’s local save module

This module will give us one consistent place to save and load ticket, category, and mission progress. In VS Code:

1. In the Explorer, open the `game/src` folder.
2. Create a folder named `state`.
3. Inside it, create a file named `gameState.js`.
4. Paste in this code and save the file:

```js
const STORAGE_KEY = 'nfc-hunt-save'
const SAVE_VERSION = 1

export const REQUIRED_MISSION_IDS = [
  'mission-1',
  'mission-2',
  'mission-3',
  'mission-4',
  'mission-5',
]

const ALL_MISSION_IDS = [...REQUIRED_MISSION_IDS, 'mission-6']

export function createInitialGameState() {
  return {
    version: SAVE_VERSION,
    playerCategory: null,
    ticketNumber: null,
    missions: Object.fromEntries(
      ALL_MISSION_IDS.map((missionId) => [
        missionId,
        {
          lineIndex: 0,
          itemCollected: false,
          storyWrapped: false,
        },
      ]),
    ),
    mission6Unlocked: false,
    completionInstructionsSeen: false,
    finalInstructionsSeen: false,
  }
}

function isValidGameState(state) {
  return (
    state !== null &&
    typeof state === 'object' &&
    state.version === SAVE_VERSION &&
    (state.playerCategory === null ||
      state.playerCategory === 'regular' ||
      state.playerCategory === 'add-on') &&
    (state.ticketNumber === null || typeof state.ticketNumber === 'string') &&
    state.missions !== null &&
    typeof state.missions === 'object' &&
    typeof state.mission6Unlocked === 'boolean' &&
    typeof state.completionInstructionsSeen === 'boolean' &&
    typeof state.finalInstructionsSeen === 'boolean' &&
    ALL_MISSION_IDS.every((missionId) => {
      const mission = state.missions[missionId]

      return (
        mission !== null &&
        typeof mission === 'object' &&
        Number.isInteger(mission.lineIndex) &&
        mission.lineIndex >= 0 &&
        typeof mission.itemCollected === 'boolean' &&
        typeof mission.storyWrapped === 'boolean'
      )
    })
  )
}

export function loadGameState() {
  const savedState = window.localStorage.getItem(STORAGE_KEY)

  if (savedState === null) {
    return createInitialGameState()
  }

  const parsedState = JSON.parse(savedState)

  if (!isValidGameState(parsedState)) {
    throw new Error('The saved game data is invalid or from an unsupported version.')
  }

  return parsedState
}

export function saveGameState(state) {
  if (!isValidGameState(state)) {
    throw new Error('Cannot save invalid game data.')
  }

  window.localStorage.setItem(STORAGE_KEY, JSON.stringify(state))
}

export function clearGameState() {
  window.localStorage.removeItem(STORAGE_KEY)
}
```

This step only creates the save module; it won’t change how the game behaves yet. When you’ve created and saved the file, tell me what happened (or paste any VS Code error), and we’ll move on to the next step.

Next we’ll make each QR code set the player’s category. For now, you can test the URLs manually; you don’t need to make or print QR codes yet. **This step only sets and saves the category. It won’t change the game screen yet.**

### Step 2: Add the category bootstrap route

In VS Code, create [CategoryBootstrap.jsx](/workspaces/NFC-Hunt/game/src/components/CategoryBootstrap.jsx) inside `game/src/components` and paste in:

```jsx
import { useEffect, useState } from 'react'
import { useNavigate, useParams } from 'react-router-dom'
import { loadGameState, saveGameState } from '../state/gameState'

function CategoryBootstrap() {
  const { category } = useParams()
  const navigate = useNavigate()
  const [error, setError] = useState('')

  useEffect(() => {
    if (category !== 'regular' && category !== 'add-on') {
      navigate('/', { replace: true })
      return
    }

    try {
      const gameState = loadGameState()
      saveGameState({ ...gameState, playerCategory: category })
      navigate('/', { replace: true })
    } catch (error) {
      setError(
        error instanceof Error
          ? error.message
          : 'Unable to save the player category.',
      )
    }
  }, [category, navigate])

  if (error) {
    return <p role="alert">{error}</p>
  }

  return <p>Setting up your game...</p>
}

export default CategoryBootstrap
```

Now open [App.jsx](/workspaces/NFC-Hunt/game/src/App.jsx):

1. Add this import alongside the other component imports:

   ```jsx
   import CategoryBootstrap from './components/CategoryBootstrap'
   ```

2. Add this route inside `<Routes>`, before the existing routes:

   ```jsx
   <Route
     path="/bootstrap/:category"
     element={<CategoryBootstrap />}
   />
   ```

Save both files. With the Vite server running, test the regular-player URL:

```text
http://localhost:5173/NFC-Hunt/#/bootstrap/regular
```

It should briefly show “Setting up your game…” and then redirect to the game’s opening screen. The add-on URL is:

```text
http://localhost:5173/NFC-Hunt/#/bootstrap/add-on
```

Tell me whether the regular URL redirects successfully, or what error you see.

Yes. Replace the category-name check in `CategoryBootstrap.jsx` with a lookup from each fixed token to its category. You don’t need to send me the tokens; paste them directly into your file.

Replace the file contents with this, substituting your generated values for `PASTE_REGULAR_TOKEN_HERE` and `PASTE_ADD_ON_TOKEN_HERE`:

```jsx
import { useEffect, useState } from 'react'
import { useNavigate, useParams } from 'react-router-dom'
import { loadGameState, saveGameState } from '../state/gameState'

const CATEGORY_BY_TOKEN = {
  PASTE_REGULAR_TOKEN_HERE: 'regular',
  PASTE_ADD_ON_TOKEN_HERE: 'add-on',
}

function CategoryBootstrap() {
  const { token } = useParams()
  const navigate = useNavigate()
  const [error, setError] = useState('')

  useEffect(() => {
    const category = CATEGORY_BY_TOKEN[token]

    if (!category) {
      navigate('/', { replace: true })
      return
    }

    try {
      const gameState = loadGameState()
      saveGameState({ ...gameState, playerCategory: category })
      navigate('/', { replace: true })
    } catch (error) {
      setError(
        error instanceof Error
          ? error.message
          : 'Unable to save the player category.',
      )
    }
  }, [token, navigate])

  if (error) {
    return <p role="alert">{error}</p>
  }

  return <p>Setting up your game...</p>
}

export default CategoryBootstrap
```

Make sure each token is inside quotes as an object key, like:

```js
'0123456789abcdef0123456789abcdef': 'regular',
```

Then, in `App.jsx`, change the bootstrap route to use the parameter name `token`:

```jsx
<Route path="/bootstrap/:token" element={<CategoryBootstrap />} />
```

The URL shape stays the same, but now it contains your opaque token rather than the category name. After saving, tell me whether VS Code or the browser shows an error; then we’ll test one token.

