@@ -1,114 +1,114 @@
 import { useEffect, useState } from 'react'
 import './WelcomeScreen.css'

 const dialogueLines = [
   'Welcome Miss Hunter to Wang Chuan Tech Pte. Ltd.!',
   "I am OTTO-MENGPO, your guide for today's VR experience.",
   'Today we will visit the Spirit Realm and lend a hand to some troubled spirits!',
   'Are you ready?',
 ]

 function WelcomeScreen() {
   const [lineIndex, setLineIndex] = useState(0)
   const [visibleText, setVisibleText] = useState('')
   const [ticketNumber, setTicketNumber] = useState('')
   const [playerName, setPlayerName] = useState('')

   const currentLine = dialogueLines[lineIndex]
   const isLastLine = lineIndex === dialogueLines.length - 1
   const spielComplete = isLastLine && visibleText === currentLine

   useEffect(() => {
     if (visibleText.length >= currentLine.length) {
       return undefined
     }

     const timer = window.setTimeout(() => {
       setVisibleText(currentLine.slice(0, visibleText.length + 1))
     }, 50)

     return () => window.clearTimeout(timer)
   }, [currentLine, visibleText])

   function handleAdvance() {
     if (visibleText !== currentLine) {
       setVisibleText(currentLine)
       return
     }

     if (!isLastLine) {
       setLineIndex((index) => index + 1)
       setVisibleText('')
     }
   }

   return (
     <main className="welcome-page" onClick={!spielComplete ? handleAdvance : undefined}>
       <div className="welcome-content">
         <div className="welcome-advance">
           <img
             className="welcome-otto"
             src={`${import.meta.env.BASE_URL}images/otto.png`}
             alt="Otto, your guide"
           />

           <span className="welcome-bubble">
             <span className="welcome-dialogue" aria-live="polite">
               {visibleText}
             </span>
           </span>
         </div>

         {(() => {
           const showTapPrompt = !spielComplete && visibleText === currentLine

           return (
             <p
               className={`welcome-tap-prompt${showTapPrompt ? '' : ' is-hidden'}`}
               aria-hidden={!showTapPrompt}
             >
                 ▼ Tap to continue
             </p>
           )
         })()}

         {spielComplete && (
           <form className="welcome-ticket-form">
             <label className="sr-only" htmlFor="player-name">
                 Player name
             </label>
             <input
                 id="player-name"
                 className="welcome-input"
                 type="text"
                 placeholder="Your Name"
                 autoComplete="off"
                 value={playerName}
                 onChange={(event) => setPlayerName(event.target.value)}
             />
             <label className="sr-only" htmlFor="ticket-number">
               Ticket number
             </label>
             <input
               id="ticket-number"
               className="welcome-input"
               type="text"
               placeholder="Your Ticket Number"
               autoComplete="off"
               value={ticketNumber}
               onChange={(event) => setTicketNumber(event.target.value)}
             />
             <button className="welcome-enter" type="button" disabled>
               ENTER
             </button>
             <p className="welcome-hint">
               Ticket entry will be enabled in the next step.
             </p>
           </form>
         )}
       </div>
     </main>
   )
 }

 export default WelcomeScreen

response.value:
The stack is moving because `.welcome-page` centers the **entire** `.welcome-content`. When the name and ticket form appears, the content gets taller and its center changes. Anchor the stack from the top instead, so new fields extend downward.

In [WelcomeScreen.css](/workspaces/NFC-Hunt/game/src/components/WelcomeScreen.css), replace the `.welcome-page` and `.welcome-content` rules with these:

```css
.welcome-page {
  position: fixed;
  inset: 0;
  z-index: 1;
  display: block;
  overflow-y: auto;
  padding: 33vh 1rem 2rem;
  color: #e0faff;
  background: #000;
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  box-sizing: border-box;
}

.welcome-content {
  display: flex;
  width: min(100%, 450px);
  flex-direction: column;
  align-items: center;
  gap: clamp(30px, 8vh, 60px);
  margin: 0 auto;
}
```

The `33vh` top padding fixes Otto and the textbox in place relative to the screen height. The form remains below them in the normal layout. If the form doesn’t fit on a short screen, the landing page can scroll down.

Save the CSS and preview again. Otto and the textbox should stay in the same position when the fields appear.

